/* Apple IIe Enhanced (128 KB): see apple2.h.
 * Zero static .bss footprint: all RAM, ROM, GCR nibble tracks and audio buffers live in KSEG0(EMU_RAM_PHYS).
 */
#pragma GCC optimize("O2")
#include "apple2.h"

#ifndef APPLE2_HOST
#include "hw.h"
#endif

#define A2_CYCLES_LINE   65u
#define A2_LINES_FRAME   262u
#define A2_FRAME_CYCLES  (A2_CYCLES_LINE * A2_LINES_FRAME) /* 17,030 cycles @ 1,020,484 Hz */
#define A2_CLOCK_HZ      1020484u
#define A2_VBL_CYCLES    4550u
#define A2_TRACKS        35
#define A2_NIB_LEN       6656
#define A2_DSK_SIZE      143360u
#define A2_NIB_SIZE      (35u * 6656u)
#define A2_RING_LEN      4096u
#define A2_MAX_TOGGLES   4096u

struct apple2_ws {
    u8 main_ram[0x10000];               /* $0000..$BFFF (48K) + $D000..$FFFF (12K LC) */
    u8 main_lc_alt[0x1000];             /* $D000..$DFFF alternate 4K LC bank */
    u8 aux_ram[0x10000];                /* 64 KB Auxiliary 80-col / DHR RAM */
    u8 aux_lc_alt[0x1000];              /* Auxiliary $D000..$DFFF alternate 4K LC bank */
    u8 rom_main[0x4000];                /* 16 KB Apple IIe Enhanced ROM ($C000..$FFFF) */
    u8 rom_char[0x1000];                /* 4 KB Apple IIe Enhanced Video ROM */
    u8 rom_disk2[0x0100];               /* 256 B Slot 6 Disk II 16-Sector P5A PROM */
    u8 nib[A2_TRACKS][A2_NIB_LEN];      /* 35 GCR 6-and-2 encoded nibble tracks */
    u8 dsk_save[A2_DSK_SIZE];           /* Decoded 140 KB .dsk / .po image for .sav writeback */
    u8 bin_stage[0xC000];               /* Optional single-file binary payload */
    u32 spk_cyc[A2_MAX_TOGGLES];        /* Cycle timestamps of $C030 speaker toggles in current frame */
    s16 snd_ring[A2_RING_LEN];
    u16 lores_pal[16];
    u16 hires_pal[8];                   /* Black, Green, Violet, White, Black2, Orange, Blue, White2 */
    u8 dummy_sink[256];
    u8 sav_dummy[16];
};

#ifdef APPLE2_HOST
static struct apple2_ws apple2_host_ws;
#define WS (&apple2_host_ws)
#else
#define WS ((struct apple2_ws *)KSEG0(EMU_RAM_PHYS))
#endif

#define RGB15_A2(r, g, b) ((u16)((((r) >> 3) & 31u) | ((((g) >> 3) & 31u) << 5) | ((((b) >> 3) & 31u) << 10)))

