/* Mockingboard AY-3-8910 + minimal 6522 VIA timer (Slot 4: $C400..$C4FF) */
struct mb_chip {
    u8 ora, orb, ddra, ddrb, acr, ifr, ier;
    u16 t1c, t1l;
    u8 ay_sel, ay_reg[16];
    u32 ay_ph[3], ay_nph, ay_lfsr;
    u8 ay_out[3];
};

static struct {
    /* WDC 65C02 CPU */
    u8 a, x, y, sp, p;
    u16 pc;
    u8 jam, irq_line;
    u32 cyc;                            /* cycles within current frame (0..17030) */
    u32 total_frames;

    /* 256-page fast MMU lookup ($00..$FF; NULL = $C0xx I/O or unmapped) */
    const u8 *rdp[256];
    u8 *wrp[256];

    /* MMU & Video Soft-Switches */
    u8 sw_80store, sw_ramrd, sw_ramwrt, sw_intcxrom, sw_altzp, sw_slotc3rom, sw_intc8rom;
    u8 sw_80col, sw_altchar, sw_text, sw_mixed, sw_page2, sw_hires, sw_an3;
    u8 lc_read_ram, lc_write_state, lc_alt_bank;

    /* Keyboard & Joystick / Paddles */
    u8 kbd_latch;                       /* bit 7 = key strobe, bits 6..0 = ASCII */
    u8 any_key_down;
    u8 pb[3];                           /* Open-Apple (PB0), Closed-Apple (PB1), PB2 */
    u8 pdl_val[4];                      /* 0..255 (128 = center) */
    u32 pdl_trigger_cyc;
    u8 pdl_frame_seen;
    char type_q[512];
    u16 type_head, type_tail;
    u8 type_delay;
    u8 prev_hid[8];
    int prev_hid_n;
    u16 prev_pad;

    /* Disk II Controller (Slot 6) */
    u8 has_disk, is_prodos, is_nib_only, disk_dirty;
    u8 trk_dirty[A2_TRACKS];
    u8 dsk_phases, dsk_q4_motor, dsk_selected, dsk_q6, dsk_q7, dsk_latch, dsk_shifting;
    u32 dsk_last_read_cyc;
    int dsk_qtrk;                       /* quarter-track 0..138 (track = dsk_qtrk >> 2) */
    u16 dsk_pos[A2_TRACKS];
    u32 dsk_motor_off_frames;

    /* Single-file .bin stage */
    u8 has_bin, bin_injected;
    u16 bin_addr;
    u32 bin_len;

    /* Audio ($C030 speaker + Mockingboard) */
    u8 spk_level;
    u32 spk_ntog;
    s32 snd_dc;
    u32 snd_hz, snd_rem, snd_head, snd_count;
    struct mb_chip mb[2];

    int out_w;
    char info[96];
} S;

static void a2_zero(void *dst, u32 n)
{
    u8 *p = (u8 *)dst;
    for (u32 i = 0; i < n; i++) p[i] = 0;
}

static void a2_copy(void *dst, const void *src, u32 n)
{
    u8 *d = (u8 *)dst;
    const u8 *s = (const u8 *)src;
    for (u32 i = 0; i < n; i++) d[i] = s[i];
}

static void put_s(char **p, const char *end, const char *s)
{
    while (*s && *p < end) *(*p)++ = *s++;
    **p = 0;
}

static void put_u(char **p, const char *end, u32 v)
{
    char d[12]; int n = 0;
    do d[n++] = (char)('0' + (v % 10u)); while (v /= 10u);
    while (n && *p < end) *(*p)++ = d[--n];
    **p = 0;
}

/* ---- Disk II 6-and-2 GCR Nibblizer & De-nibblizer ---- */
static void nib_encode_track(const u8 *trk_src, u8 track_no, const u8 *log_ord, u8 *out_nib)
{
    u32 p = 0;
    u8 pri[256], sec[86];
    for (u8 phys = 0; phys < 16u; phys++) {
        u8 lsec = log_ord[phys];
        const u8 *sdata = trk_src + (u32)lsec * 256u;
        a2_zero(sec, sizeof(sec));
        for (int i = 0; i < 256; i++) {
            u8 v = sdata[i];
            pri[i] = v >> 2;
            u32 sh = (u32)(i / 86) * 2u;
            u8 b0 = (u8)(((v & 1u) << 1) << sh);
            u8 b1 = (u8)(((v & 2u) >> 1) << sh);
            sec[i % 86] |= (u8)(b0 | b1);
        }
        /* Gap 1 (48 sync bytes) */
        for (int g = 0; g < 48; g++) out_nib[p++] = 0xFFu;
        /* Address field: D5 AA 96 + vol(254) + trk + sec + csum + DE AA EB */
        u8 vol = 254u, csum = (u8)(vol ^ track_no ^ phys);
        out_nib[p++] = 0xD5u; out_nib[p++] = 0xAAu; out_nib[p++] = 0x96u;
        out_nib[p++] = ((vol >> 1) & 0x55u) | 0xAAu;      out_nib[p++] = (vol & 0x55u) | 0xAAu;
        out_nib[p++] = ((track_no >> 1) & 0x55u) | 0xAAu; out_nib[p++] = (track_no & 0x55u) | 0xAAu;
        out_nib[p++] = ((phys >> 1) & 0x55u) | 0xAAu;     out_nib[p++] = (phys & 0x55u) | 0xAAu;
        out_nib[p++] = ((csum >> 1) & 0x55u) | 0xAAu;     out_nib[p++] = (csum & 0x55u) | 0xAAu;
        out_nib[p++] = 0xDEu; out_nib[p++] = 0xAAu; out_nib[p++] = 0xEBu;
        /* Gap 2 (5 sync bytes) + Data field: D5 AA AD + 342 GCR + csum + DE AA EB */
        for (int g = 0; g < 5; g++) out_nib[p++] = 0xFFu;
        out_nib[p++] = 0xD5u; out_nib[p++] = 0xAAu; out_nib[p++] = 0xADu;
        u8 prev = 0;
        for (int i = 0; i < 86; i++)  { out_nib[p++] = gcr_enc62[(sec[i] ^ prev) & 63u]; prev = sec[i]; }
        for (int i = 0; i < 256; i++) { out_nib[p++] = gcr_enc62[(pri[i] ^ prev) & 63u]; prev = pri[i]; }
        out_nib[p++] = gcr_enc62[prev & 63u];
        out_nib[p++] = 0xDEu; out_nib[p++] = 0xAAu; out_nib[p++] = 0xEBu;
    }
    while (p < A2_NIB_LEN) out_nib[p++] = 0xFFu;
}

static int gcr_dec_byte(u8 b)
{
    for (int i = 0; i < 64; i++)
        if (gcr_enc62[i] == b) return i;
    return -1;
}

static void nib_decode_track(const u8 *nib, const u8 *log_ord, u8 *trk_dst)
{
    u32 pos = 0;
    while (pos < A2_NIB_LEN) {
        int found_a = -1;
        for (u32 k = 0; k < A2_NIB_LEN; k++) {
            u32 idx = pos + k;
            if (idx >= A2_NIB_LEN) break;
            if (nib[idx % A2_NIB_LEN] == 0xD5u &&
                nib[(idx + 1u) % A2_NIB_LEN] == 0xAAu &&
                nib[(idx + 2u) % A2_NIB_LEN] == 0x96u) {
                found_a = (int)(idx + 3u);
                break;
            }
        }
        if (found_a < 0) break;
        u8 phys = (u8)((((nib[(found_a + 4) % A2_NIB_LEN] & 0x55u) << 1) |
                         (nib[(found_a + 5) % A2_NIB_LEN] & 0x55u)) & 15u);
        u8 lsec = log_ord[phys];
        u8 *dst = trk_dst + (u32)lsec * 256u;

        int found_d = -1;
        u32 dstart = (u32)found_a + 11u;
        for (u32 k = 0; k < 120u; k++) {
            u32 idx = dstart + k;
            if (nib[idx % A2_NIB_LEN] == 0xD5u &&
                nib[(idx + 1u) % A2_NIB_LEN] == 0xAAu &&
                nib[(idx + 2u) % A2_NIB_LEN] == 0xADu) {
                found_d = (int)(idx + 3u);
                break;
            }
        }
        if (found_d < 0) break;
        a2_zero(dst, 256);
        u8 prev = 0;
        u32 cur = (u32)found_d;
        int ok = 1;
        for (int j = 0; j < 86; j++) {
            int w = gcr_dec_byte(nib[cur++ % A2_NIB_LEN]);
            if (w < 0) { ok = 0; break; }
            u8 v = (u8)w ^ prev;
            prev = v;
            for (int k = 0; k < 3; k++) {
                int off = j + k * 86;
                if (off < 256)
                    dst[off] |= (u8)(((v & 2u) >> 1) | ((v & 1u) << 1));
                v >>= 2;
            }
        }
        if (ok) {
            for (int j = 0; j < 256; j++) {
                int w = gcr_dec_byte(nib[cur++ % A2_NIB_LEN]);
                if (w < 0) break;
                u8 v = (u8)w ^ prev;
                prev = v;
                dst[j] |= (u8)(v << 2);
            }
        }
        pos = cur + 4u;
    }
}

static int stepper_move(u8 phases, int prev_step)
{
    static const signed char cog[16] = {-1, 0, 2, 1, 4, -1, 3, 2, 6, 7, -1, 0, 5, 6, 4, -1};
    int cp = cog[phases & 15u];
    if (cp < 0) return prev_step;
    int pp = prev_step & 7;
    int delta = cp - pp;
    if (delta < 0) delta += 8;
    int next = prev_step;
    if (delta < 4) {
        next = prev_step + delta;
        if (next > 136) next = 136;
    } else if (delta > 4) {
        next = prev_step + delta - 8;
        if (next < 0) next = 0;
    }
    return next;
}

/* ---- Apple IIe MMU 256-Page Table Rebuild ---- */
static void rebuild_mmu(void)
{
    u8 *zp_ram   = S.sw_altzp  ? WS->aux_ram : WS->main_ram;
    u8 *rd_main  = S.sw_ramrd  ? WS->aux_ram : WS->main_ram;
    u8 *wr_main  = S.sw_ramwrt ? WS->aux_ram : WS->main_ram;

    /* $0000..$01FF: Zero Page + Stack */
    S.rdp[0] = zp_ram + 0x0000; S.wrp[0] = zp_ram + 0x0000;
    S.rdp[1] = zp_ram + 0x0100; S.wrp[1] = zp_ram + 0x0100;

    /* $0200..$BFFF: 48 KB Main/Aux RAM */
    for (int p = 0x02; p < 0xC0; p++) {
        S.rdp[p] = rd_main + (p << 8);
        S.wrp[p] = wr_main + (p << 8);
    }

    /* 80STORE override on Text Page 1 ($0400..$07FF) and HiRes Page 1 ($2000..$3FFF) */
    if (S.sw_80store) {
        u8 *vid_ram = S.sw_page2 ? WS->aux_ram : WS->main_ram;
        for (int p = 0x04; p <= 0x07; p++) {
            S.rdp[p] = vid_ram + (p << 8);
            S.wrp[p] = vid_ram + (p << 8);
        }
        if (S.sw_hires) {
            for (int p = 0x20; p <= 0x3F; p++) {
                S.rdp[p] = vid_ram + (p << 8);
                S.wrp[p] = vid_ram + (p << 8);
            }
        }
    }

    /* $C000..$CFFF: Soft-switches ($C0) + Slots / Internal IIe ROM ($C1..$CF)
       Keep $C3 and $CF in io_read so C300 sets intC8ROM and CFFF clears intC8ROM! */
    for (int p = 0xC0; p <= 0xCF; p++) {
        S.rdp[p] = 0;
        S.wrp[p] = WS->dummy_sink;
    }
    S.wrp[0xC0] = 0;
    S.wrp[0xC4] = 0; /* Slot 4 Mockingboard */
    S.wrp[0xCF] = 0;
    if (S.sw_intcxrom) {
        for (int p = 0xC1; p <= 0xCF; p++)
            if (p != 0xCF) S.rdp[p] = WS->rom_main + ((p - 0xC0) << 8);
    } else {
        S.rdp[0xC6] = WS->rom_disk2;    /* Slot 6 Disk II boot PROM */
        if (S.sw_intc8rom) {
            for (int p = 0xC8; p <= 0xCE; p++)
                S.rdp[p] = WS->rom_main + ((p - 0xC0) << 8);
        }
    }

    /* $D000..$FFFF: Language Card RAM vs Internal IIe ROM */
    u8 *lc_base = S.sw_altzp ? WS->aux_ram    : WS->main_ram;
    u8 *lc_alt  = S.sw_altzp ? WS->aux_lc_alt : WS->main_lc_alt;
    int lc_wr   = (S.lc_write_state >= 2u);

    for (int p = 0xD0; p <= 0xFF; p++) {
        u8 *ram_p = (p < 0xE0 && S.lc_alt_bank) ? (lc_alt + ((p - 0xD0) << 8))
                                                : (lc_base + (p << 8));
        S.rdp[p] = S.lc_read_ram ? ram_p : (WS->rom_main + ((p - 0xC0) << 8));
        S.wrp[p] = lc_wr ? ram_p : WS->dummy_sink;
    }
}

/* ---- Mockingboard (Slot 4: $C400..$C4FF) ---- */
static void mb_write_psg(struct mb_chip *m)
{
    u8 cmd = m->orb & 7u;
    if (cmd == 7u) {                    /* Latch AY register */
        m->ay_sel = m->ora & 15u;
    } else if (cmd == 6u) {             /* Write AY register */
        if (m->ay_sel < 16u)
            m->ay_reg[m->ay_sel] = m->ora;
    } else if (cmd == 5u) {             /* Read AY register */
        if (m->ay_sel < 16u)
            m->ora = m->ay_reg[m->ay_sel];
    } else if ((m->orb & 4u) == 0u) {   /* Reset AY */
        a2_zero(m->ay_reg, sizeof(m->ay_reg));
    }
}

static u8 mb_read(u16 addr)
{
    struct mb_chip *m = &S.mb[(addr >> 7) & 1u];
    switch (addr & 15u) {
    case 0x00: m->ifr &= ~0x10u; return m->orb;
    case 0x01: case 0x0F: m->ifr &= ~0x02u; return m->ora;
    case 0x02: return m->ddrb;
    case 0x03: return m->ddra;
    case 0x04: m->ifr &= ~0x40u; return (u8)(m->t1c & 0xFFu);
    case 0x05: return (u8)(m->t1c >> 8);
    case 0x06: return (u8)(m->t1l & 0xFFu);
    case 0x07: return (u8)(m->t1l >> 8);
    case 0x0B: return m->acr;
    case 0x0D: return (u8)(m->ifr | ((m->ifr & m->ier & 0x7Fu) ? 0x80u : 0u));
    case 0x0E: return (u8)(m->ier | 0x80u);
    }
    return 0xFFu;
}

static void mb_write(u16 addr, u8 val)
{
    struct mb_chip *m = &S.mb[(addr >> 7) & 1u];
    switch (addr & 15u) {
    case 0x00: m->orb = val; mb_write_psg(m); break;
    case 0x01: case 0x0F: m->ora = val; break;
    case 0x02: m->ddrb = val; break;
    case 0x03: m->ddra = val; break;
    case 0x04: case 0x06: m->t1l = (u16)((m->t1l & 0xFF00u) | val); break;
    case 0x05:
        m->t1l = (u16)((m->t1l & 0x00FFu) | ((u16)val << 8));
        m->t1c = m->t1l;
        m->ifr &= ~0x40u;
        break;
    case 0x07:
        m->t1l = (u16)((m->t1l & 0x00FFu) | ((u16)val << 8));
        m->ifr &= ~0x40u;
        break;
    case 0x0B: m->acr = val; break;
    case 0x0D: m->ifr &= (u8)~(val & 0x7Fu); break;
    case 0x0E:
        if (val & 0x80u) m->ier |= (val & 0x7Fu);
        else             m->ier &= (u8)~(val & 0x7Fu);
        break;
    }
}

/* ---- $C0xx Soft-Switches & Slot I/O ---- */
static void lc_access(u8 ss, int is_write)
{
    S.lc_alt_bank = ((ss >> 3) & 1u) == 0u;
    switch (ss & 3u) {
    case 0: S.lc_read_ram = 1; S.lc_write_state = 0; break;
    case 1: S.lc_read_ram = 0; if (!is_write) S.lc_write_state++; break;
    case 2: S.lc_read_ram = 0; S.lc_write_state = 0; break;
    case 3: S.lc_read_ram = 1; if (!is_write) S.lc_write_state++; break;
    }
    if (is_write && S.lc_write_state == 1u) S.lc_write_state = 0;
    if (S.lc_write_state > 2u) S.lc_write_state = 2u;
    rebuild_mmu();
}

static void toggle_speaker(void)
{
    if (S.spk_ntog < A2_MAX_TOGGLES)
        WS->spk_cyc[S.spk_ntog++] = S.cyc;
    else
        S.spk_level ^= 1u;
}

static u8 disk2_io(u8 reg, int is_write, u8 val)
{
    reg &= 15u;
    if (reg < 8u) {
        u8 ph = reg >> 1;
        if (reg & 1u) S.dsk_phases |= (u8)(1u << ph);
        else          S.dsk_phases &= (u8)~(1u << ph);
        if (S.dsk_selected == 0)
            S.dsk_qtrk = stepper_move(S.dsk_phases, S.dsk_qtrk);
        return (reg & 1u) ? 0u : S.dsk_latch;
    }
    switch (reg) {
    case 0x08: S.dsk_q4_motor = 0; S.dsk_motor_off_frames = 60; return S.dsk_latch;
    case 0x09: S.dsk_q4_motor = 1; S.dsk_motor_off_frames = 0;  return 0;
    case 0x0A: S.dsk_selected = 0; return S.dsk_latch;
    case 0x0B: S.dsk_selected = 1; return 0;
    case 0x0C: S.dsk_q6 = 0; break;
    case 0x0D: S.dsk_q6 = 1; break;
    case 0x0E: S.dsk_q7 = 0; break;
    case 0x0F: S.dsk_q7 = 1; break;
    }
    int spinning = S.dsk_q4_motor || (S.dsk_motor_off_frames > 0);
    if (S.has_disk && S.dsk_selected == 0 && spinning) {
        int trk = S.dsk_qtrk >> 2;
        if (trk < 0) trk = 0;
        if (trk >= A2_TRACKS) trk = A2_TRACKS - 1;
        if (!S.dsk_q6) {
            if (!S.dsk_q7) {            /* Q6L/Q7L: Shift / Read nibble */
                u16 p = S.dsk_pos[trk];
                if (S.dsk_shifting && WS->nib[trk][p] == 0xFFu && (p & 3u) == 0u) {
                    /* Show shifting bit7=0 in sync gaps so DOS spin-sense never stalls, while keeping 1-read data speed! */
                    S.dsk_shifting = 0;
                    S.dsk_latch = 0x7Fu;
                } else {
                    S.dsk_latch = WS->nib[trk][p];
                    S.dsk_pos[trk] = (u16)((p + 1u) % A2_NIB_LEN);
                    S.dsk_shifting = 1;
                }
            } else {                    /* Q6L/Q7H: Shift out / Write nibble */
                u16 p = S.dsk_pos[trk];
                S.dsk_shifting = 0;
                WS->nib[trk][p] = S.dsk_latch;
                S.dsk_pos[trk] = (u16)((p + 1u) % A2_NIB_LEN);
                S.trk_dirty[trk] = 1;
                S.disk_dirty = 1;
            }
        } else {
            if (!S.dsk_q7) {            /* Q6H/Q7L: Write-protect sense (0 = writable) */
                S.dsk_latch = S.is_nib_only ? 0x80u : 0x00u;
            } else if (is_write) {      /* Q6H/Q7H: Load data latch */
                S.dsk_latch = val;
            }
        }
    }
    return (reg & 1u) ? 0u : S.dsk_latch;
}

static void video_switch(u8 lo)
{
    u8 mmu_chg = 0;
    switch (lo) {
    case 0x50: S.sw_text = 0; break;
    case 0x51: S.sw_text = 1; break;
    case 0x52: S.sw_mixed = 0; break;
    case 0x53: S.sw_mixed = 1; break;
    case 0x54: if (S.sw_page2) { S.sw_page2 = 0; mmu_chg = S.sw_80store; } break;
    case 0x55: if (!S.sw_page2) { S.sw_page2 = 1; mmu_chg = S.sw_80store; } break;
    case 0x56: if (S.sw_hires) { S.sw_hires = 0; mmu_chg = S.sw_80store; } break;
    case 0x57: if (!S.sw_hires) { S.sw_hires = 1; mmu_chg = S.sw_80store; } break;
    case 0x5E: S.sw_an3 = 0; break;
    case 0x5F: S.sw_an3 = 1; break;
    }
    if (mmu_chg) rebuild_mmu();
}

static __attribute__((noinline)) u8 io_read(u16 addr)
{
    u8 hi = (u8)(addr >> 8);
    if (hi != 0xC0u) {
        if (hi < 0xC1u || hi > 0xCFu) return 0xFFu;
        if (hi == 0xC4u && !S.sw_intcxrom)
            return mb_read(addr);
        if (hi == 0xC3u && !S.sw_intcxrom && !S.sw_slotc3rom) {
            if (!S.sw_intc8rom) { S.sw_intc8rom = 1; rebuild_mmu(); }
            return WS->rom_main[(addr - 0xC000u) & 0x3FFFu];
        }
        if (addr == 0xCFFFu) {
            if (S.sw_intc8rom) { S.sw_intc8rom = 0; rebuild_mmu(); }
            return S.sw_intcxrom ? WS->rom_main[0x0FFFu] : 0xFFu;
        }
        if (S.sw_intcxrom || (hi >= 0xC8u && S.sw_intc8rom))
            return WS->rom_main[(addr - 0xC000u) & 0x3FFFu];
        return 0xFFu;
    }

    u8 lo = (u8)(addr & 0xFFu);
    if (lo < 0x10u) return S.kbd_latch;
    if (lo == 0x10u) {
        u8 akd = S.any_key_down ? 0x80u : 0x00u;
        S.kbd_latch &= 0x7Fu;
        return (u8)(akd | (S.kbd_latch & 0x7Fu));
    }
    switch (lo) {
    case 0x11: return S.lc_alt_bank ? 0x80u : 0x00u;
    case 0x12: return S.lc_read_ram ? 0x80u : 0x00u;
    case 0x13: return S.sw_ramrd ? 0x80u : 0x00u;
    case 0x14: return S.sw_ramwrt ? 0x80u : 0x00u;
    case 0x15: return S.sw_intcxrom ? 0x80u : 0x00u;
    case 0x16: return S.sw_altzp ? 0x80u : 0x00u;
    case 0x17: return S.sw_slotc3rom ? 0x80u : 0x00u;
    case 0x18: return S.sw_80store ? 0x80u : 0x00u;
    case 0x19: return (S.cyc <= A2_VBL_CYCLES) ? 0x80u : 0x00u; /* IIe VBL: $80 during VBlank! */
    case 0x1A: return S.sw_text ? 0x80u : 0x00u;
    case 0x1B: return S.sw_mixed ? 0x80u : 0x00u;
    case 0x1C: return S.sw_page2 ? 0x80u : 0x00u;
    case 0x1D: return S.sw_hires ? 0x80u : 0x00u;
    case 0x1E: return S.sw_altchar ? 0x80u : 0x00u;
    case 0x1F: return S.sw_80col ? 0x80u : 0x00u;
    }
    if ((lo & 0xF0u) == 0x30u) { toggle_speaker(); return 0; }
    if (lo >= 0x50u && lo <= 0x5Fu) { video_switch(lo); return 0; }
    if (lo >= 0x60u && lo <= 0x6Fu) {
        switch (lo & 7u) {
        case 1: return S.pb[0] ? 0x80u : 0x00u;
        case 2: return S.pb[1] ? 0x80u : 0x00u;
        case 3: return S.pb[2] ? 0x80u : 0x00u;
        case 4: case 5: case 6: case 7: {
            u8 idx = (lo & 7u) - 4u;
            u32 dur = (u32)S.pdl_val[idx] * 11u;
            u32 elapsed = S.pdl_frame_seen ? (S.cyc >= S.pdl_trigger_cyc ? S.cyc - S.pdl_trigger_cyc : 9999u) : 9999u;
            return (elapsed < dur) ? 0x80u : 0x00u;
        }
        }
        return 0;
    }
    if ((lo & 0xF0u) == 0x70u) {
        S.pdl_trigger_cyc = S.cyc;
        S.pdl_frame_seen = 1;
        return 0;
    }
    if (lo >= 0x80u && lo <= 0x8Fu) { lc_access(lo & 15u, 0); return 0; }
    if (lo >= 0xE0u && lo <= 0xEFu) return disk2_io(lo & 15u, 0, 0);
    return 0;
}

static __attribute__((noinline)) void io_write(u16 addr, u8 val)
{
    u8 hi = (u8)(addr >> 8);
    if (hi != 0xC0u) {
        if (hi == 0xC4u && !S.sw_intcxrom) mb_write(addr, val);
        if (addr == 0xCFFFu && S.sw_intc8rom) { S.sw_intc8rom = 0; rebuild_mmu(); }
        return;
    }
    u8 lo = (u8)(addr & 0xFFu);
    if (lo < 0x10u) {
        switch (lo) {
        case 0x00: S.sw_80store = 0; rebuild_mmu(); break;
        case 0x01: S.sw_80store = 1; rebuild_mmu(); break;
        case 0x02: S.sw_ramrd = 0; rebuild_mmu(); break;
        case 0x03: S.sw_ramrd = 1; rebuild_mmu(); break;
        case 0x04: S.sw_ramwrt = 0; rebuild_mmu(); break;
        case 0x05: S.sw_ramwrt = 1; rebuild_mmu(); break;
        case 0x06: S.sw_intcxrom = 0; rebuild_mmu(); break;
        case 0x07: S.sw_intcxrom = 1; rebuild_mmu(); break;
        case 0x08: S.sw_altzp = 0; rebuild_mmu(); break;
        case 0x09: S.sw_altzp = 1; rebuild_mmu(); break;
        case 0x0A: S.sw_slotc3rom = 0; rebuild_mmu(); break;
        case 0x0B: S.sw_slotc3rom = 1; rebuild_mmu(); break;
        case 0x0C: S.sw_80col = 0; break;
        case 0x0D: S.sw_80col = 1; break;
        case 0x0E: S.sw_altchar = 0; break;
        case 0x0F: S.sw_altchar = 1; break;
        }
        return;
    }
    if (lo >= 0x10u && lo <= 0x1Fu) { S.kbd_latch &= 0x7Fu; return; }
    if ((lo & 0xF0u) == 0x30u) { toggle_speaker(); return; }
    if (lo >= 0x50u && lo <= 0x5Fu) { video_switch(lo); return; }
    if ((lo & 0xF0u) == 0x70u) { S.pdl_trigger_cyc = S.cyc; S.pdl_frame_seen = 1; return; }
    if (lo >= 0x80u && lo <= 0x8Fu) { lc_access(lo & 15u, 1); return; }
    if (lo >= 0xE0u && lo <= 0xEFu) { (void)disk2_io(lo & 15u, 1, val); return; }
}

static inline u8 cpu_rd(u16 addr)
{
    const u8 *p = S.rdp[addr >> 8];
    S.cyc++;
    return p ? p[addr & 0xFFu] : io_read(addr);
}

static inline void cpu_wr(u16 addr, u8 val)
{
    u8 *p = S.wrp[addr >> 8];
    S.cyc++;
    if (p) p[addr & 0xFFu] = val;
    else   io_write(addr, val);
}

/* ---- Full WDC 65C02 CPU Core ---- */
#define FC 0x01u
#define FZ 0x02u
#define FI 0x04u
#define FD 0x08u
#define FB 0x10u
#define FU 0x20u
#define FV 0x40u
#define FN 0x80u

static inline void set_nz(u8 v) { S.p = (u8)((S.p & ~(FN | FZ)) | (v & FN) | (v ? 0u : FZ)); }
static inline void push8(u8 v)  { cpu_wr((u16)(0x0100u | S.sp--), v); }
static inline u8 pull8(void)    { return cpu_rd((u16)(0x0100u | ++S.sp)); }

static void op_adc(u8 v)
{
    u32 a = S.a, c = S.p & FC, bin = a + v + c;
    if (S.p & FD) {
        S.cyc++;                        /* 65C02 takes +1 cycle for valid N/Z in decimal mode */
        u32 lo = (a & 15u) + (v & 15u) + c;
        if (lo > 9u) lo += 6u;
        u32 r = (a & 0xF0u) + (v & 0xF0u) + (lo > 15u ? 0x10u : 0u) + (lo & 15u);
        S.p &= (u8)~(FN | FV | FZ | FC);
        if (~(a ^ v) & (a ^ r) & 0x80u) S.p |= FV;
        if (r > 0x99u) r += 0x60u;
        if (r > 0xFFu) S.p |= FC;
        S.a = (u8)r;
        set_nz(S.a);
    } else {
        S.p = (u8)((S.p & ~(FN | FV | FZ | FC)) | (bin & FN) | ((bin & 0xFFu) ? 0u : FZ) |
                   ((~(a ^ v) & (a ^ bin) & 0x80u) ? FV : 0u) | (bin > 0xFFu ? FC : 0u));
        S.a = (u8)bin;
    }
}

static void op_sbc(u8 v)
{
    u32 a = S.a, nb = S.p & FC, dif = a - v - (1u - nb);
    if (S.p & FD) {
        S.cyc++;
        s32 lo = (s32)(a & 15u) - (s32)(v & 15u) - (s32)(1u - nb);
        s32 r = (s32)dif;
        if (r < 0) r -= 0x60;
        if (lo < 0) r -= 0x06;
        S.p = (u8)((S.p & ~(FN | FV | FZ | FC)) | (((a ^ v) & (a ^ dif) & 0x80u) ? FV : 0u) |
                   (dif < 0x100u ? FC : 0u));
        S.a = (u8)r;
        set_nz(S.a);
    } else {
        S.p = (u8)((S.p & ~(FN | FV | FZ | FC)) | (dif & FN) | ((dif & 0xFFu) ? 0u : FZ) |
                   (((a ^ v) & (a ^ dif) & 0x80u) ? FV : 0u) | (dif < 0x100u ? FC : 0u));
        S.a = (u8)dif;
    }
}

static inline void op_cmp(u8 r, u8 v) { S.p = (u8)((S.p & ~FC) | (r >= v ? FC : 0u)); set_nz((u8)(r - v)); }
static inline u8 op_asl(u8 v) { S.p = (u8)((S.p & ~FC) | (v >> 7)); v = (u8)(v << 1); set_nz(v); return v; }
static inline u8 op_lsr(u8 v) { S.p = (u8)((S.p & ~FC) | (v & 1u)); v >>= 1; set_nz(v); return v; }
static inline u8 op_rol(u8 v) { u8 c = S.p & FC; S.p = (u8)((S.p & ~FC) | (v >> 7)); v = (u8)((v << 1) | c); set_nz(v); return v; }
static inline u8 op_ror(u8 v) { u8 c = S.p & FC; S.p = (u8)((S.p & ~FC) | (v & 1u)); v = (u8)((v >> 1) | (c << 7)); set_nz(v); return v; }

static inline u16 ea_zp(void)  { return cpu_rd(S.pc++); }
static inline u16 ea_zpx(void) { u8 z = cpu_rd(S.pc++); S.cyc++; return (u8)(z + S.x); }
static inline u16 ea_zpy(void) { u8 z = cpu_rd(S.pc++); S.cyc++; return (u8)(z + S.y); }
static inline u16 ea_abs(void) { u16 a = cpu_rd(S.pc++); return (u16)(a | ((u16)cpu_rd(S.pc++) << 8)); }
static inline u16 ea_abx(int wr) { u16 b = ea_abs(), a = (u16)(b + S.x); if (wr || ((b ^ a) & 0xFF00u)) S.cyc++; return a; }
static inline u16 ea_aby(int wr) { u16 b = ea_abs(), a = (u16)(b + S.y); if (wr || ((b ^ a) & 0xFF00u)) S.cyc++; return a; }
static inline u16 ea_izp(void) { u8 z = cpu_rd(S.pc++); u16 a = cpu_rd(z); return (u16)(a | ((u16)cpu_rd((u8)(z + 1u)) << 8)); }
static inline u16 ea_izx(void) { u8 z = cpu_rd(S.pc++); S.cyc++; z = (u8)(z + S.x); u16 a = cpu_rd(z); return (u16)(a | ((u16)cpu_rd((u8)(z + 1u)) << 8)); }
static inline u16 ea_izy(int wr) { u8 z = cpu_rd(S.pc++); u16 b = cpu_rd(z); b |= (u16)(cpu_rd((u8)(z + 1u)) << 8); u16 a = (u16)(b + S.y); if (wr || ((b ^ a) & 0xFF00u)) S.cyc++; return a; }

static void cpu_step(void)
{
    if (S.jam) { S.cyc += 4; return; }
    if (S.irq_line && !(S.p & FI)) {
        S.cyc += 2;
        push8((u8)(S.pc >> 8));
        push8((u8)S.pc);
        push8((u8)((S.p & ~FB) | FU));
        S.p = (u8)((S.p | FI) & ~FD);
        u8 lo = cpu_rd(0xFFFEu);
        S.pc = (u16)(lo | ((u16)cpu_rd(0xFFFFu) << 8));
        return;
    }

    u8 op = cpu_rd(S.pc++);
    u16 ea;
    u8 v;

#define BR(cond) do { s32 off = (signed char)cpu_rd(S.pc++); if (cond) { u16 t = (u16)(S.pc + off); S.cyc += ((S.pc ^ t) & 0xFF00u) ? 2u : 1u; S.pc = t; } } while (0)
#define RMW(addr_expr, fn) do { ea = (addr_expr); v = cpu_rd(ea); S.cyc++; v = (fn); cpu_wr(ea, v); } while (0)

    /* Handle Rockwell/WDC RMBn / SMBn / BBRn / BBSn ($x7 / $xF) */
    if ((op & 0x07u) == 0x07u) {
        u8 bit = (u8)(1u << ((op >> 4) & 7u));
        u8 z = cpu_rd(S.pc++);
        v = cpu_rd(z);
        if ((op & 0x0Fu) == 0x07u) {    /* RMBn ($07..$77) / SMBn ($87..$F7) */
            S.cyc++;
            cpu_wr(z, (op & 0x80u) ? (u8)(v | bit) : (u8)(v & ~bit));
        } else {                        /* BBRn ($0F..$7F) / BBSn ($8F..$FF) */
            s32 off = (signed char)cpu_rd(S.pc++);
            int take = (op & 0x80u) ? ((v & bit) != 0u) : ((v & bit) == 0u);
            if (take) {
                u16 t = (u16)(S.pc + off);
                S.cyc += ((S.pc ^ t) & 0xFF00u) ? 2u : 1u;
                S.pc = t;
            }
        }
        return;
    }

    switch (op) {
    /* ORA */
    case 0x09: set_nz(S.a |= cpu_rd(S.pc++)); break;
    case 0x05: set_nz(S.a |= cpu_rd(ea_zp())); break;
    case 0x15: set_nz(S.a |= cpu_rd(ea_zpx())); break;
    case 0x0D: set_nz(S.a |= cpu_rd(ea_abs())); break;
    case 0x1D: set_nz(S.a |= cpu_rd(ea_abx(0))); break;
    case 0x19: set_nz(S.a |= cpu_rd(ea_aby(0))); break;
    case 0x01: set_nz(S.a |= cpu_rd(ea_izx())); break;
    case 0x11: set_nz(S.a |= cpu_rd(ea_izy(0))); break;
    case 0x12: set_nz(S.a |= cpu_rd(ea_izp())); break;
    /* AND */
    case 0x29: set_nz(S.a &= cpu_rd(S.pc++)); break;
    case 0x25: set_nz(S.a &= cpu_rd(ea_zp())); break;
    case 0x35: set_nz(S.a &= cpu_rd(ea_zpx())); break;
    case 0x2D: set_nz(S.a &= cpu_rd(ea_abs())); break;
    case 0x3D: set_nz(S.a &= cpu_rd(ea_abx(0))); break;
    case 0x39: set_nz(S.a &= cpu_rd(ea_aby(0))); break;
    case 0x21: set_nz(S.a &= cpu_rd(ea_izx())); break;
    case 0x31: set_nz(S.a &= cpu_rd(ea_izy(0))); break;
    case 0x32: set_nz(S.a &= cpu_rd(ea_izp())); break;
    /* EOR */
    case 0x49: set_nz(S.a ^= cpu_rd(S.pc++)); break;
    case 0x45: set_nz(S.a ^= cpu_rd(ea_zp())); break;
    case 0x55: set_nz(S.a ^= cpu_rd(ea_zpx())); break;
    case 0x4D: set_nz(S.a ^= cpu_rd(ea_abs())); break;
    case 0x5D: set_nz(S.a ^= cpu_rd(ea_abx(0))); break;
    case 0x59: set_nz(S.a ^= cpu_rd(ea_aby(0))); break;
    case 0x41: set_nz(S.a ^= cpu_rd(ea_izx())); break;
    case 0x51: set_nz(S.a ^= cpu_rd(ea_izy(0))); break;
    case 0x52: set_nz(S.a ^= cpu_rd(ea_izp())); break;
    /* ADC */
    case 0x69: op_adc(cpu_rd(S.pc++)); break;
    case 0x65: op_adc(cpu_rd(ea_zp())); break;
    case 0x75: op_adc(cpu_rd(ea_zpx())); break;
    case 0x6D: op_adc(cpu_rd(ea_abs())); break;
    case 0x7D: op_adc(cpu_rd(ea_abx(0))); break;
    case 0x79: op_adc(cpu_rd(ea_aby(0))); break;
    case 0x61: op_adc(cpu_rd(ea_izx())); break;
    case 0x71: op_adc(cpu_rd(ea_izy(0))); break;
    case 0x72: op_adc(cpu_rd(ea_izp())); break;
    /* SBC */
    case 0xE9: op_sbc(cpu_rd(S.pc++)); break;
    case 0xE5: op_sbc(cpu_rd(ea_zp())); break;
    case 0xF5: op_sbc(cpu_rd(ea_zpx())); break;
    case 0xED: op_sbc(cpu_rd(ea_abs())); break;
    case 0xFD: op_sbc(cpu_rd(ea_abx(0))); break;
    case 0xF9: op_sbc(cpu_rd(ea_aby(0))); break;
    case 0xE1: op_sbc(cpu_rd(ea_izx())); break;
    case 0xF1: op_sbc(cpu_rd(ea_izy(0))); break;
    case 0xF2: op_sbc(cpu_rd(ea_izp())); break;
    /* STA / STX / STY / STZ */
    case 0x85: cpu_wr(ea_zp(), S.a); break;
    case 0x95: cpu_wr(ea_zpx(), S.a); break;
    case 0x8D: cpu_wr(ea_abs(), S.a); break;
    case 0x9D: cpu_wr(ea_abx(1), S.a); break;
    case 0x99: cpu_wr(ea_aby(1), S.a); break;
    case 0x81: cpu_wr(ea_izx(), S.a); break;
    case 0x91: cpu_wr(ea_izy(1), S.a); break;
    case 0x92: cpu_wr(ea_izp(), S.a); break;
    case 0x86: cpu_wr(ea_zp(), S.x); break;
    case 0x96: cpu_wr(ea_zpy(), S.x); break;
    case 0x8E: cpu_wr(ea_abs(), S.x); break;
    case 0x84: cpu_wr(ea_zp(), S.y); break;
    case 0x94: cpu_wr(ea_zpx(), S.y); break;
    case 0x8C: cpu_wr(ea_abs(), S.y); break;
    case 0x64: cpu_wr(ea_zp(), 0); break;
    case 0x74: cpu_wr(ea_zpx(), 0); break;
    case 0x9C: cpu_wr(ea_abs(), 0); break;
    case 0x9E: cpu_wr(ea_abx(1), 0); break;
    /* LDA / LDX / LDY */
    case 0xA9: set_nz(S.a = cpu_rd(S.pc++)); break;
    case 0xA5: set_nz(S.a = cpu_rd(ea_zp())); break;
    case 0xB5: set_nz(S.a = cpu_rd(ea_zpx())); break;
    case 0xAD: set_nz(S.a = cpu_rd(ea_abs())); break;
    case 0xBD: set_nz(S.a = cpu_rd(ea_abx(0))); break;
    case 0xB9: set_nz(S.a = cpu_rd(ea_aby(0))); break;
    case 0xA1: set_nz(S.a = cpu_rd(ea_izx())); break;
    case 0xB1: set_nz(S.a = cpu_rd(ea_izy(0))); break;
    case 0xB2: set_nz(S.a = cpu_rd(ea_izp())); break;
    case 0xA2: set_nz(S.x = cpu_rd(S.pc++)); break;
    case 0xA6: set_nz(S.x = cpu_rd(ea_zp())); break;
    case 0xB6: set_nz(S.x = cpu_rd(ea_zpy())); break;
    case 0xAE: set_nz(S.x = cpu_rd(ea_abs())); break;
    case 0xBE: set_nz(S.x = cpu_rd(ea_aby(0))); break;
    case 0xA0: set_nz(S.y = cpu_rd(S.pc++)); break;
    case 0xA4: set_nz(S.y = cpu_rd(ea_zp())); break;
    case 0xB4: set_nz(S.y = cpu_rd(ea_zpx())); break;
    case 0xAC: set_nz(S.y = cpu_rd(ea_abs())); break;
    case 0xBC: set_nz(S.y = cpu_rd(ea_abx(0))); break;
    /* CMP / CPX / CPY */
    case 0xC9: op_cmp(S.a, cpu_rd(S.pc++)); break;
    case 0xC5: op_cmp(S.a, cpu_rd(ea_zp())); break;
    case 0xD5: op_cmp(S.a, cpu_rd(ea_zpx())); break;
    case 0xCD: op_cmp(S.a, cpu_rd(ea_abs())); break;
    case 0xDD: op_cmp(S.a, cpu_rd(ea_abx(0))); break;
    case 0xD9: op_cmp(S.a, cpu_rd(ea_aby(0))); break;
    case 0xC1: op_cmp(S.a, cpu_rd(ea_izx())); break;
    case 0xD1: op_cmp(S.a, cpu_rd(ea_izy(0))); break;
    case 0xD2: op_cmp(S.a, cpu_rd(ea_izp())); break;
    case 0xE0: op_cmp(S.x, cpu_rd(S.pc++)); break;
    case 0xE4: op_cmp(S.x, cpu_rd(ea_zp())); break;
    case 0xEC: op_cmp(S.x, cpu_rd(ea_abs())); break;
    case 0xC0: op_cmp(S.y, cpu_rd(S.pc++)); break;
    case 0xC4: op_cmp(S.y, cpu_rd(ea_zp())); break;
    case 0xCC: op_cmp(S.y, cpu_rd(ea_abs())); break;
    /* BIT / TSB / TRB */
    case 0x89: v = cpu_rd(S.pc++); S.p = (u8)((S.p & ~FZ) | ((v & S.a) ? 0u : FZ)); break;
    case 0x24: v = cpu_rd(ea_zp());  S.p = (u8)((S.p & ~(FN|FV|FZ)) | (v & 0xC0u) | ((v & S.a) ? 0u : FZ)); break;
    case 0x34: v = cpu_rd(ea_zpx()); S.p = (u8)((S.p & ~(FN|FV|FZ)) | (v & 0xC0u) | ((v & S.a) ? 0u : FZ)); break;
    case 0x2C: v = cpu_rd(ea_abs()); S.p = (u8)((S.p & ~(FN|FV|FZ)) | (v & 0xC0u) | ((v & S.a) ? 0u : FZ)); break;
    case 0x3C: v = cpu_rd(ea_abx(0));S.p = (u8)((S.p & ~(FN|FV|FZ)) | (v & 0xC0u) | ((v & S.a) ? 0u : FZ)); break;
    case 0x04: ea = ea_zp();  v = cpu_rd(ea); S.p = (u8)((S.p & ~FZ) | ((v & S.a) ? 0u : FZ)); S.cyc++; cpu_wr(ea, (u8)(v | S.a)); break;
    case 0x0C: ea = ea_abs(); v = cpu_rd(ea); S.p = (u8)((S.p & ~FZ) | ((v & S.a) ? 0u : FZ)); S.cyc++; cpu_wr(ea, (u8)(v | S.a)); break;
    case 0x14: ea = ea_zp();  v = cpu_rd(ea); S.p = (u8)((S.p & ~FZ) | ((v & S.a) ? 0u : FZ)); S.cyc++; cpu_wr(ea, (u8)(v & ~S.a)); break;
    case 0x1C: ea = ea_abs(); v = cpu_rd(ea); S.p = (u8)((S.p & ~FZ) | ((v & S.a) ? 0u : FZ)); S.cyc++; cpu_wr(ea, (u8)(v & ~S.a)); break;
    /* Shifts & INC / DEC */
    case 0x0A: S.cyc++; S.a = op_asl(S.a); break;
    case 0x2A: S.cyc++; S.a = op_rol(S.a); break;
    case 0x4A: S.cyc++; S.a = op_lsr(S.a); break;
    case 0x6A: S.cyc++; S.a = op_ror(S.a); break;
    case 0x1A: S.cyc++; set_nz(++S.a); break;
    case 0x3A: S.cyc++; set_nz(--S.a); break;
    case 0x06: RMW(ea_zp(),    op_asl(v)); break;
    case 0x16: RMW(ea_zpx(),   op_asl(v)); break;
    case 0x0E: RMW(ea_abs(),   op_asl(v)); break;
    case 0x1E: RMW(ea_abx(1),  op_asl(v)); break;
    case 0x26: RMW(ea_zp(),    op_rol(v)); break;
    case 0x36: RMW(ea_zpx(),   op_rol(v)); break;
    case 0x2E: RMW(ea_abs(),   op_rol(v)); break;
    case 0x3E: RMW(ea_abx(1),  op_rol(v)); break;
    case 0x46: RMW(ea_zp(),    op_lsr(v)); break;
    case 0x56: RMW(ea_zpx(),   op_lsr(v)); break;
    case 0x4E: RMW(ea_abs(),   op_lsr(v)); break;
    case 0x5E: RMW(ea_abx(1),  op_lsr(v)); break;
    case 0x66: RMW(ea_zp(),    op_ror(v)); break;
    case 0x76: RMW(ea_zpx(),   op_ror(v)); break;
    case 0x6E: RMW(ea_abs(),   op_ror(v)); break;
    case 0x7E: RMW(ea_abx(1),  op_ror(v)); break;
    case 0xC6: RMW(ea_zp(),    (u8)(v - 1u)); set_nz(v); break;
    case 0xD6: RMW(ea_zpx(),   (u8)(v - 1u)); set_nz(v); break;
    case 0xCE: RMW(ea_abs(),   (u8)(v - 1u)); set_nz(v); break;
    case 0xDE: RMW(ea_abx(1),  (u8)(v - 1u)); set_nz(v); break;
    case 0xE6: RMW(ea_zp(),    (u8)(v + 1u)); set_nz(v); break;
    case 0xF6: RMW(ea_zpx(),   (u8)(v + 1u)); set_nz(v); break;
    case 0xEE: RMW(ea_abs(),   (u8)(v + 1u)); set_nz(v); break;
    case 0xFE: RMW(ea_abx(1),  (u8)(v + 1u)); set_nz(v); break;
    /* Jumps / Subroutines / Branches */
    case 0x4C: S.pc = ea_abs(); break;
    case 0x6C: { u16 p = ea_abs(); S.cyc++; u8 lo = cpu_rd(p); S.pc = (u16)(lo | ((u16)cpu_rd((u16)(p + 1u)) << 8)); break; }
    case 0x7C: { u16 p = (u16)(ea_abs() + S.x); S.cyc++; u8 lo = cpu_rd(p); S.pc = (u16)(lo | ((u16)cpu_rd((u16)(p + 1u)) << 8)); break; }
    case 0x20: { u8 lo = cpu_rd(S.pc++); S.cyc++; push8((u8)(S.pc >> 8)); push8((u8)S.pc); S.pc = (u16)(lo | ((u16)cpu_rd(S.pc) << 8)); break; }
    case 0x60: { S.cyc += 2; u8 lo = pull8(); S.pc = (u16)((lo | ((u16)pull8() << 8)) + 1u); S.cyc++; break; }
    case 0x40: { S.cyc += 2; S.p = (u8)((pull8() & ~FB) | FU); u8 lo = pull8(); S.pc = (u16)(lo | ((u16)pull8() << 8)); break; }
    case 0x00: { (void)cpu_rd(S.pc++); push8((u8)(S.pc >> 8)); push8((u8)S.pc); push8((u8)(S.p | FB | FU)); S.p = (u8)((S.p | FI) & ~FD); u8 lo = cpu_rd(0xFFFEu); S.pc = (u16)(lo | ((u16)cpu_rd(0xFFFFu) << 8)); break; }
    case 0x80: BR(1); break;
    case 0x10: BR(!(S.p & FN)); break;
    case 0x30: BR(S.p & FN); break;
    case 0x50: BR(!(S.p & FV)); break;
    case 0x70: BR(S.p & FV); break;
    case 0x90: BR(!(S.p & FC)); break;
    case 0xB0: BR(S.p & FC); break;
    case 0xD0: BR(!(S.p & FZ)); break;
    case 0xF0: BR(S.p & FZ); break;
    /* Stack & Register Transfers & Flags */
    case 0x08: S.cyc++; push8((u8)(S.p | FB | FU)); break;
    case 0x28: S.cyc += 2; S.p = (u8)((pull8() & ~FB) | FU); break;
    case 0x48: S.cyc++; push8(S.a); break;
    case 0x68: S.cyc += 2; set_nz(S.a = pull8()); break;
    case 0xDA: S.cyc++; push8(S.x); break;
    case 0xFA: S.cyc += 2; set_nz(S.x = pull8()); break;
    case 0x5A: S.cyc++; push8(S.y); break;
    case 0x7A: S.cyc += 2; set_nz(S.y = pull8()); break;
    case 0x18: S.cyc++; S.p &= ~FC; break;
    case 0x38: S.cyc++; S.p |= FC; break;
    case 0x58: S.cyc++; S.p &= ~FI; break;
    case 0x78: S.cyc++; S.p |= FI; break;
    case 0xB8: S.cyc++; S.p &= ~FV; break;
    case 0xD8: S.cyc++; S.p &= ~FD; break;
    case 0xF8: S.cyc++; S.p |= FD; break;
    case 0x88: S.cyc++; set_nz(--S.y); break;
    case 0xC8: S.cyc++; set_nz(++S.y); break;
    case 0xCA: S.cyc++; set_nz(--S.x); break;
    case 0xE8: S.cyc++; set_nz(++S.x); break;
    case 0x98: S.cyc++; set_nz(S.a = S.y); break;
    case 0xA8: S.cyc++; set_nz(S.y = S.a); break;
    case 0x8A: S.cyc++; set_nz(S.a = S.x); break;
    case 0xAA: S.cyc++; set_nz(S.x = S.a); break;
    case 0x9A: S.cyc++; S.sp = S.x; break;
    case 0xBA: S.cyc++; set_nz(S.x = S.sp); break;
    case 0xDB: S.jam = 1; S.pc--; break; /* STP */
    case 0xCB: S.cyc += 2; break;        /* WAI */
    /* 65C02 multi-byte NOPs */
    case 0x02: case 0x22: case 0x42: case 0x62: case 0x82: case 0xC2: case 0xE2:
    case 0x44: case 0x54: case 0xD4: case 0xF4:
        (void)cpu_rd(S.pc++); break;
    case 0x5C: case 0xDC: case 0xFC:
        (void)ea_abs(); S.cyc++; break;
    default:
        S.cyc++;
        break;
    }
#undef BR
#undef RMW
}

/* ---- Video Renderer (Text 40/80, Lo-Res/DGR, NTSC Artifact Hi-Res & Double Hi-Res) ---- */
static inline u16 text_row_base(int row, int page2)
{
    u16 base = page2 ? 0x0800u : 0x0400u;
    return (u16)(base + ((row & 7) << 7) + (row >> 3) * 40);
}

static inline u16 hires_line_base(int y, int page2)
{
    u16 base = page2 ? 0x4000u : 0x2000u;
    return (u16)(base + ((y & 7) << 10) + (((y >> 3) & 7) << 7) + (y >> 6) * 40);
}

static inline u8 char_row_bits(u8 ch, int ry, int flash_on)
{
    int vid6 = (ch & 0x40u) != 0u;
    int vid7 = (ch & 0x80u) != 0u;
    u8 idx = ch & 0x3Fu;
    if (vid6 && (vid7 || S.sw_altchar)) idx = (u8)(idx + 0x40u);
    if (vid7 || (vid6 && flash_on && !S.sw_altchar)) idx = (u8)(idx + 0x80u);
    /* IIe Video Enhanced ROM has 0=lit, 1=dark, LSB=leftmost column */
    return (u8)(~WS->rom_char[(u32)idx * 8u + (u32)ry] & 0x7Fu);
}

static void render_video(u16 *picture)
{
    int page2 = S.sw_page2 && !S.sw_80store;
    int flash_on = ((S.total_frames >> 4) & 1u) != 0u;
    int is_dres = !S.sw_text && S.sw_80col && !S.sw_an3;
    int wide = (S.sw_text && S.sw_80col) || (S.sw_mixed && S.sw_80col) || is_dres;
    S.out_w = wide ? A2_W_HI : A2_W_STD;
    if (!picture) return;

    u16 white = WS->lores_pal[15];
    u16 black = WS->lores_pal[0];

    for (int y = 0; y < A2_H; y++) {
        u16 *dst = picture + y * S.out_w;
        int in_text = S.sw_text || (S.sw_mixed && y >= 160);

        if (in_text) {
            int row = y >> 3, ry = y & 7;
            u16 off = text_row_base(row, page2);
            if (S.sw_80col) {
                for (int col = 0; col < 40; col++) {
                    u8 b_even = char_row_bits(WS->aux_ram[off + col], ry, flash_on);
                    u8 b_odd  = char_row_bits(WS->main_ram[off + col], ry, flash_on);
                    for (int i = 0; i < 7; i++) *dst++ = (b_even & (1u << i)) ? white : black;
                    for (int i = 0; i < 7; i++) *dst++ = (b_odd  & (1u << i)) ? white : black;
                }
            } else {
                for (int col = 0; col < 40; col++) {
                    u8 b = char_row_bits(WS->main_ram[off + col], ry, flash_on);
                    if (wide) {
                        for (int i = 0; i < 7; i++) {
                            u16 px = (b & (1u << i)) ? white : black;
                            *dst++ = px; *dst++ = px;
                        }
                    } else {
                        for (int i = 0; i < 7; i++) *dst++ = (b & (1u << i)) ? white : black;
                    }
                }
            }
        } else if (S.sw_hires) {
            u16 off = hires_line_base(y, page2);
            if (is_dres) {              /* Double Hi-Res: 560 dots -> 140 4-bit NTSC color nybbles */
                u8 bits[564];
                int bp = 0;
                bits[bp++] = 0; bits[bp++] = 0;
                for (int col = 0; col < 40; col++) {
                    u8 a = WS->aux_ram[off + col];
                    u8 m = WS->main_ram[off + col];
                    for (int i = 0; i < 7; i++) bits[bp++] = (a >> i) & 1u;
                    for (int i = 0; i < 7; i++) bits[bp++] = (m >> i) & 1u;
                }
                bits[bp++] = 0; bits[bp++] = 0;
                for (int x = 0; x < 560; x++) {
                    int base = x & ~3;
                    u8 cidx = (u8)(bits[2 + base] | (bits[2 + base + 1] << 1) |
                                   (bits[2 + base + 2] << 2) | (bits[2 + base + 3] << 3));
                    dst[x] = WS->lores_pal[cidx];
                }
            } else {                    /* Standard 280x192 NTSC Artifact Color Hi-Res */
                u8 dots[284];
                u8 palbit[284];
                dots[0] = 0; palbit[0] = 0;
                for (int col = 0; col < 40; col++) {
                    u8 b = WS->main_ram[off + col];
                    u8 pb = (b >> 7) & 1u;
                    for (int i = 0; i < 7; i++) {
                        dots[1 + col * 7 + i] = (b >> i) & 1u;
                        palbit[1 + col * 7 + i] = pb;
                    }
                }
                dots[281] = 0; palbit[281] = 0;
                for (int x = 0; x < 280; x++) {
                    u8 d_prev = dots[x], d_cur = dots[x + 1], d_next = dots[x + 2];
                    u8 pb = palbit[x + 1];
                    u16 col15;
                    if (d_cur) {
                        if (d_prev || d_next)
                            col15 = WS->hires_pal[3];               /* White */
                        else
                            col15 = WS->hires_pal[(pb ? 4 : 0) + ((x & 1) ? 1 : 2)]; /* Odd=Green/Orange, Even=Violet/Blue */
                    } else {
                        if (d_prev && d_next && palbit[x] == palbit[x + 2])
                            col15 = WS->hires_pal[(palbit[x] ? 4 : 0) + (((x - 1) & 1) ? 1 : 2)]; /* Artifact fill between 101 */
                        else
                            col15 = WS->hires_pal[0];               /* Black */
                    }
                    if (wide) { *dst++ = col15; *dst++ = col15; }
                    else      { *dst++ = col15; }
                }
            }
        } else {                        /* Lo-Res (40x48) or Double Lo-Res (80x48) */
            int row = y >> 3, bot = (y & 4) != 0;
            u16 off = text_row_base(row, page2);
            if (is_dres) {
                for (int col = 0; col < 40; col++) {
                    u8 ca = bot ? (WS->aux_ram[off + col] >> 4) : (WS->aux_ram[off + col] & 15u);
                    /* Aux Lo-Res nybbles are rotated left 1 bit relative to Main! */
                    ca = (u8)(((ca << 1) | (ca >> 3)) & 15u);
                    u8 cm = bot ? (WS->main_ram[off + col] >> 4) : (WS->main_ram[off + col] & 15u);
                    u16 pa = WS->lores_pal[ca], pm = WS->lores_pal[cm];
                    for (int i = 0; i < 7; i++) *dst++ = pa;
                    for (int i = 0; i < 7; i++) *dst++ = pm;
                }
            } else {
                for (int col = 0; col < 40; col++) {
                    u8 cm = bot ? (WS->main_ram[off + col] >> 4) : (WS->main_ram[off + col] & 15u);
                    u16 pm = WS->lores_pal[cm];
                    int w = wide ? 14 : 7;
                    for (int i = 0; i < w; i++) *dst++ = pm;
                }
            }
        }
    }
}

/* ---- Keyboard & Gamepad Input ---- */
static void latch_key(u8 ascii)
{
    if (ascii >= 'a' && ascii <= 'z')
        ascii = (u8)(ascii - 32u);      /* Applesoft & classic games expect uppercase ASCII */
    S.kbd_latch = (u8)(0x80u | (ascii & 0x7Fu));
}

void apple2_typed(char c)
{
    u8 ch = (u8)c;
    if (ch == '\n') ch = '\r';
    u16 next = (u16)((S.type_tail + 1u) % sizeof(S.type_q));
    if (next != S.type_head) {
        S.type_q[S.type_tail] = (char)ch;
        S.type_tail = next;
    }
}

static u8 hid_to_ascii(u8 u, int shift, int ctrl)
{
    if (u >= 0x04 && u <= 0x1D) {
        u8 c = (u8)('A' + (u - 0x04));
        return ctrl ? (u8)(c & 0x1Fu) : c;
    }
    if (u >= 0x1E && u <= 0x26) {
        static const char *sn = "!@#$%^&*(";
        return shift ? (u8)sn[u - 0x1E] : (u8)('1' + (u - 0x1E));
    }
    if (u == 0x27) return shift ? ')' : '0';
    switch (u) {
    case 0x28: case 0x58: return 0x0Du; /* Return */
    case 0x2A: case 0x50: return 0x08u; /* Left / Backspace */
    case 0x4F: return 0x15u;            /* Right (Ctrl-U) */
    case 0x51: return 0x0Au;            /* Down (Ctrl-J) */
    case 0x52: return 0x0Bu;            /* Up (Ctrl-K) */
    case 0x2C: return ' ';
    case 0x2D: return shift ? '_' : '-';
    case 0x2E: return shift ? '+' : '=';
    case 0x2F: return shift ? '{' : '[';
    case 0x30: return shift ? '}' : ']';
    case 0x31: return shift ? '|' : '\\';
    case 0x33: return shift ? ':' : ';';
    case 0x34: return shift ? '"' : '\'';
    case 0x36: return shift ? '<' : ',';
    case 0x37: return shift ? '>' : '.';
    case 0x38: return shift ? '?' : '/';
    }
    return 0;
}

void apple2_keyboard(const u8 *usages, int n)
{
    int shift = 0, ctrl = 0, alt_l = 0, alt_r = 0;
    S.any_key_down = 0;
    for (int i = 0; i < n; i++) {
        u8 u = usages[i];
        if (u == 0xE1 || u == 0xE5) shift = 1;
        if (u == 0xE0 || u == 0xE4) ctrl = 1;
        if (u == 0xE2) alt_l = 1;
        if (u == 0xE6) alt_r = 1;
        if (u >= 0x04 && u < 0xE0) S.any_key_down = 1;
    }
    S.pb[0] = (u8)alt_l;
    S.pb[1] = (u8)alt_r;

    for (int i = 0; i < n; i++) {
        u8 u = usages[i];
        if (u >= 0xE0) continue;
        int was = 0;
        for (int j = 0; j < S.prev_hid_n; j++)
            if (S.prev_hid[j] == u) { was = 1; break; }
        if (!was) {
            u8 asc = hid_to_ascii(u, shift, ctrl);
            if (asc) latch_key(asc);
        }
    }
    S.prev_hid_n = n > 8 ? 8 : n;
    for (int i = 0; i < S.prev_hid_n; i++)
        S.prev_hid[i] = usages[i];
}

/* ---- Audio Synthesis (48 kHz Sub-Frame $C030 Speaker + Mockingboard AY) ---- */
static const s16 mb_vol[16] = {
    0, 60, 90, 130, 190, 270, 380, 540, 760, 1080, 1520, 2150, 3050, 4300, 6100, 8500
};

static void render_audio_frame(void)
{
    if (!S.snd_hz) {
        S.spk_ntog = 0;
        return;
    }
    u32 num = A2_FRAME_CYCLES * S.snd_hz + S.snd_rem;
    u32 nsamp = num / A2_CLOCK_HZ;
    S.snd_rem = num % A2_CLOCK_HZ;

    u32 tog_idx = 0;
    u32 cyc_fp = 0;
    u32 cyc_step_fp = (A2_CLOCK_HZ << 8) / S.snd_hz; /* 8-bit frac cycles per sample */
    u32 ay_step = 63780u * 256u / S.snd_hz;          /* 1.020484 MHz / 16 = 63,780 Hz */

    for (u32 s = 0; s < nsamp; s++) {
        u32 c0 = cyc_fp >> 8;
        cyc_fp += cyc_step_fp;
        u32 c1 = cyc_fp >> 8;
        if (c1 <= c0) c1 = c0 + 1u;

        /* Integrate speaker level across [c0, c1) for alias-free 1-bit sound! */
        u32 span = c1 - c0;
        u32 hi_cyc = 0;
        u32 cur = c0;
        while (tog_idx < S.spk_ntog && WS->spk_cyc[tog_idx] < c1) {
            u32 tc = WS->spk_cyc[tog_idx++];
            if (tc > cur) {
                if (S.spk_level) hi_cyc += (tc - cur);
                cur = tc;
            }
            S.spk_level ^= 1u;
        }
        if (S.spk_level && c1 > cur)
            hi_cyc += (c1 - cur);

        s32 spk_val = (s32)((hi_cyc * 18000u) / span);

        /* Mockingboard dual AY-3-8910 */
        s32 mb_val = 0;
        for (int chip = 0; chip < 2; chip++) {
            struct mb_chip *m = &S.mb[chip];
            if (!((m->ay_reg[8] | m->ay_reg[9] | m->ay_reg[10]) & 0x1Fu))
                continue;
            u32 np = (m->ay_reg[6] & 0x1Fu) ? (m->ay_reg[6] & 0x1Fu) : 1u;
            m->ay_nph += ay_step;
            while (m->ay_nph >= (np << 9)) {
                m->ay_nph -= (np << 9);
                u32 fb = ((m->ay_lfsr ^ (m->ay_lfsr >> 3)) & 1u);
                m->ay_lfsr = (m->ay_lfsr >> 1) | (fb << 16);
            }
            u8 mix = m->ay_reg[7];
            for (int ch = 0; ch < 3; ch++) {
                u32 tp = (u32)m->ay_reg[ch * 2] | (((u32)m->ay_reg[ch * 2 + 1] & 15u) << 8);
                if (!tp) tp = 1u;
                m->ay_ph[ch] += ay_step;
                while (m->ay_ph[ch] >= (tp << 8)) {
                    m->ay_ph[ch] -= (tp << 8);
                    m->ay_out[ch] ^= 1u;
                }
                int t_ok = (mix & (1u << ch)) || m->ay_out[ch];
                int n_ok = (mix & (8u << ch)) || (m->ay_lfsr & 1u);
                if (t_ok && n_ok)
                    mb_val += mb_vol[m->ay_reg[8 + ch] & 15u];
            }
        }

        s32 raw = spk_val + mb_val;
        S.snd_dc += (raw - S.snd_dc) >> 8;
        s32 out = raw - S.snd_dc;
        if (out > 32767) out = 32767;
        if (out < -32768) out = -32768;
        if (S.snd_count < A2_RING_LEN) {
            WS->snd_ring[(S.snd_head + S.snd_count) % A2_RING_LEN] = (s16)out;
            S.snd_count++;
        }
    }
    S.spk_ntog = 0;
}

/* ---- Reset & Load ---- */
void apple2_reset(void)
{
    a2_zero(WS->main_ram, sizeof(WS->main_ram));
    a2_zero(WS->main_lc_alt, sizeof(WS->main_lc_alt));
    a2_zero(WS->aux_ram, sizeof(WS->aux_ram));
    a2_zero(WS->aux_lc_alt, sizeof(WS->aux_lc_alt));

    S.sw_80store = S.sw_ramrd = S.sw_ramwrt = S.sw_intcxrom = S.sw_altzp = S.sw_slotc3rom = S.sw_intc8rom = 0;
    S.sw_80col = S.sw_altchar = S.sw_mixed = S.sw_page2 = S.sw_hires = S.sw_an3 = 0;
    S.sw_text = 1;
    S.lc_read_ram = 0;
    S.lc_write_state = 2;
    S.lc_alt_bank = 1;
    rebuild_mmu();

    S.dsk_phases = S.dsk_q4_motor = S.dsk_selected = S.dsk_q6 = S.dsk_q7 = S.dsk_latch = S.dsk_shifting = 0;
    S.dsk_qtrk = 0;
    S.dsk_motor_off_frames = 0;

    a2_zero(S.mb, sizeof(S.mb));
    S.mb[0].ay_lfsr = S.mb[1].ay_lfsr = 1u;

    S.kbd_latch = 0;
    S.pdl_val[0] = S.pdl_val[1] = S.pdl_val[2] = S.pdl_val[3] = 128u;
    S.bin_injected = 0;
    S.out_w = A2_W_STD;

    S.a = S.x = S.y = 0;
    S.sp = 0xFDu;
    S.p = FI | FU;
    S.jam = 0;
    S.irq_line = 0;
    S.cyc = 0;
    S.pc = (u16)WS->rom_main[0x3FFCu] | ((u16)WS->rom_main[0x3FFDu] << 8);
}

static int ext_is(const char *path, const char *ext)
{
    if (!path) return 0;
    const char *dot = 0;
    for (const char *p = path; *p; p++)
        if (*p == '.') dot = p + 1;
    if (!dot) return 0;
    while (*dot && *ext) {
        char a = *dot++, b = *ext++;
        if (a >= 'A' && a <= 'Z') a = (char)(a + 32);
        if (b >= 'A' && b <= 'Z') b = (char)(b + 32);
        if (a != b) return 0;
    }
    return *dot == 0 && *ext == 0;
}

const char *apple2_load(const u8 *ext_rom16k, const u8 *ext_char4k, const u8 *ext_disk256,
                        const u8 *image, u32 size, const char *path)
{
    a2_zero(&S, sizeof(S));
    for (int i = 0; i < 16; i++)
        WS->lores_pal[i] = RGB15_A2(a2_lores_rgb[i][0], a2_lores_rgb[i][1], a2_lores_rgb[i][2]);
    for (int i = 0; i < 8; i++)
        WS->hires_pal[i] = RGB15_A2(a2_hires_rgb[i][0], a2_hires_rgb[i][1], a2_hires_rgb[i][2]);

    a2_copy(WS->rom_main,  ext_rom16k  ? ext_rom16k  : apple2_rom_main,  0x4000u);
    a2_copy(WS->rom_char,  ext_char4k  ? ext_char4k  : apple2_rom_char,  0x1000u);
    a2_copy(WS->rom_disk2, ext_disk256 ? ext_disk256 : apple2_rom_disk2, 0x0100u);

    char *p = S.info, *end = S.info + sizeof(S.info) - 1;

    if (!image || size == 0) {
        apple2_reset();
        /* Without a disk in Slot 6, drop into Applesoft BASIC prompt cleanly via Ctrl-Reset after 15 frames */
        put_s(&p, end, "Apple IIe Enhanced (128 KB, Applesoft BASIC)");
        return 0;
    }

    /* Strip optional 64-byte 2MG header if present */
    if (size == A2_DSK_SIZE + 64u && image[0] == '2' && image[1] == 'I' && image[2] == 'M' && image[3] == 'G') {
        S.is_prodos = (image[0x0C] == 1u);
        image += 64u;
        size -= 64u;
    }

    if (size == A2_DSK_SIZE) {
        if (ext_is(path, "po")) S.is_prodos = 1;
        a2_copy(WS->dsk_save, image, A2_DSK_SIZE);
        const u8 *ord = S.is_prodos ? prodos_logical : dos33_logical;
        for (u8 t = 0; t < A2_TRACKS; t++)
            nib_encode_track(WS->dsk_save + (u32)t * 4096u, t, ord, WS->nib[t]);
        S.has_disk = 1;
        apple2_reset();
        put_s(&p, end, S.is_prodos ? "Apple IIe Enhanced ProDOS disk (.po), 140 KB"
                                   : "Apple IIe Enhanced Disk II (.dsk), 140 KB");
        return 0;
    }

    if (size == A2_NIB_SIZE) {
        for (u8 t = 0; t < A2_TRACKS; t++)
            a2_copy(WS->nib[t], image + (u32)t * A2_NIB_LEN, A2_NIB_LEN);
        S.has_disk = 1;
        S.is_nib_only = 1;
        apple2_reset();
        put_s(&p, end, "Apple IIe Enhanced GCR nibble disk (.nib), 227 KB");
        return 0;
    }

    /* Single-load AppleSingle ($00 $05 $16 $00) or raw binary ($0800 / DOS B-file header) */
    if (size > 4u && size <= 0xB800u) {
        u16 load_a = 0x0800u;
        const u8 *payload = image;
        u32 plen = size;
        /* Check 4-byte DOS 3.3 binary header (addr_lo, addr_hi, len_lo, len_hi) */
        u16 h_addr = (u16)image[0] | ((u16)image[1] << 8);
        u16 h_len  = (u16)image[2] | ((u16)image[3] << 8);
        if (h_len == size - 4u && h_addr >= 0x0300u && (u32)h_addr + h_len <= 0xC000u) {
            load_a = h_addr;
            payload = image + 4u;
            plen = h_len;
        }
        a2_copy(WS->bin_stage, payload, plen);
        S.has_bin = 1;
        S.bin_addr = load_a;
        S.bin_len = plen;
        apple2_reset();
        put_s(&p, end, "Apple IIe Enhanced binary, ");
        put_u(&p, end, (plen + 1023u) >> 10);
        put_s(&p, end, " KB");
        return 0;
    }

    return "unsupported Apple II image (expected 140 KB .dsk/.do/.po, 227 KB .nib, or <=46 KB .bin)";
}

void apple2_frame(u16 pad, u16 *picture)
{
    /* Map gamepad to Apple II Analog Joystick + Open/Closed Apple Buttons */
    S.pdl_val[0] = (pad & 0x40u) ? 0u : (pad & 0x80u) ? 255u : 128u;
    S.pdl_val[1] = (pad & 0x10u) ? 0u : (pad & 0x20u) ? 255u : 128u;
    S.pb[0] = (u8)(((pad & 0x01u) ? 1u : 0u) | (S.pb[0] & 2u));
    S.pb[1] = (u8)(((pad & 0x02u) ? 1u : 0u) | (S.pb[1] & 2u));
    if (pad != 0u) S.any_key_down = 1;

    /* Edge-trigger Start/Select/Buttons/Arrows to keyboard latch for menu & keyboard-only games */
    u16 new_pad = (u16)(pad & ~S.prev_pad);
    S.prev_pad = pad;
    if (new_pad & 0x08u) latch_key(0x0Du);          /* Start -> Return */
    else if (new_pad & 0x04u) latch_key(' ');       /* Select -> Space */
    else if ((new_pad & 0x01u) && !(S.kbd_latch & 0x80u)) latch_key(' ');
    else if ((pad & 0x40u) && !(S.kbd_latch & 0x80u)) latch_key(0x08u); /* Left arrow */
    else if ((pad & 0x80u) && !(S.kbd_latch & 0x80u)) latch_key(0x15u); /* Right arrow */
    else if ((pad & 0x10u) && !(S.kbd_latch & 0x80u)) latch_key(0x0Bu); /* Up arrow */
    else if ((pad & 0x20u) && !(S.kbd_latch & 0x80u)) latch_key(0x0Au); /* Down arrow */

    if (S.dsk_motor_off_frames > 0)
        S.dsk_motor_off_frames--;

    /* If booted with no disk, break out of Slot 6 search into ']' Applesoft prompt cleanly at frame 12 */
    if (!S.has_disk && S.total_frames == 12u) {
        WS->main_ram[0x03F2u] = 0x03u;
        WS->main_ram[0x03F3u] = 0xE0u;
        WS->main_ram[0x03F4u] = (u8)(0xE0u ^ 0xA5u);
        S.dsk_q4_motor = 0;
        S.pc = 0xE000u;                 /* Applesoft cold start! */
    }
    if (S.has_bin && !S.bin_injected && S.total_frames == 25u) {
        for (u32 i = 0; i < S.bin_len; i++)
            WS->main_ram[S.bin_addr + i] = WS->bin_stage[i];
        S.pc = S.bin_addr;
        S.bin_injected = 1;
    }

    /* Feed auto-type queue once previous key strobe has been cleared */
    if (S.type_head != S.type_tail) {
        if (S.type_delay > 0) {
            S.type_delay--;
        } else if (!(S.kbd_latch & 0x80u)) {
            u8 ch = (u8)S.type_q[S.type_head];
            S.type_head = (u16)((S.type_head + 1u) % sizeof(S.type_q));
            latch_key(ch);
            if (ch == '\r') S.type_delay = 6u; /* let BASIC tokenize line before next key */
        }
    }

    S.cyc = 0;
    while (S.cyc < A2_FRAME_CYCLES) {
        cpu_step();
    }
    S.total_frames++;

    render_video(picture);
    render_audio_frame();
}

int apple2_width(void)  { return S.out_w; }
int apple2_height(void) { return A2_H; }
const char *apple2_info(void) { return S.info; }

u8 *apple2_save_ram(u32 *size, int *battery)
{
    if (S.has_disk && !S.is_nib_only) {
        const u8 *ord = S.is_prodos ? prodos_logical : dos33_logical;
        for (u8 t = 0; t < A2_TRACKS; t++) {
            if (S.trk_dirty[t]) {
                nib_decode_track(WS->nib[t], ord, WS->dsk_save + (u32)t * 4096u);
                S.trk_dirty[t] = 0;
            }
        }
        *size = A2_DSK_SIZE;
        *battery = 1;
        return WS->dsk_save;
    }
    *size = 0;
    *battery = 0;
    return WS->sav_dummy;
}

int apple2_save_changed(void)
{
    int d = S.disk_dirty;
    S.disk_dirty = 0;
    return d;
}

int apple2_jammed(void) { return S.jam; }

void apple2_audio_rate(u32 hz)
{
    S.snd_hz = (hz >= 8000u && hz <= 192000u) ? hz : 0;
    S.snd_rem = 0;
    S.snd_head = S.snd_count = 0;
    S.spk_ntog = 0;
}

int apple2_audio(s16 *out, int max)
{
    int n = 0;
    while (n < max && S.snd_count) {
        out[n++] = WS->snd_ring[S.snd_head];
        S.snd_head = (S.snd_head + 1u) % A2_RING_LEN;
        S.snd_count--;
    }
    return n;
}
